#include <optional>
#include <sstream>
#include <string>

struct Point
{
    int x{};
    int y{};
};

std::optional<Point> parsePoint(const std::string& text)
{
    std::istringstream in{ text };
    char open{};
    char comma{};
    char close{};
    Point p{};
    if (!(in >> open >> p.x >> comma >> p.y >> close))
    {
        return std::nullopt;
    }
    if (open != '(' || comma != ',' || close != ')')
    {
        return std::nullopt;
    }
    in >> std::ws;
    if (!in.eof())
    {
        return std::nullopt;
    }
    return p;
}

unitTests:
bool is(const std::optional<Point>& p, int x, int y) { return p && p->x == x && p->y == y; }
TEST("the plain form") { CHECK(is(parsePoint("(3, 4)"), 3, 4)); CHECK(is(parsePoint("(-10,25)"), -10, 25)); }
TEST("spaces anywhere") { CHECK(is(parsePoint("  ( 7 ,  8 )  "), 7, 8)); }
TEST("wrong punctuation") { CHECK(!parsePoint("[3, 4]")); CHECK(!parsePoint("(3; 4)")); CHECK(!parsePoint("3, 4")); CHECK(!parsePoint("(3, 4")); }
TEST("not numbers, or parts missing") { CHECK(!parsePoint("(a, b)")); CHECK(!parsePoint("(3)")); CHECK(!parsePoint("")); }
TEST("nothing may follow") { CHECK(!parsePoint("(3, 4) extra")); CHECK(!parsePoint("(3, 4)(5, 6)")); }

